from typing import Literal
from uuid import UUID
from pydantic import Field
from app.contracts import Model, TheoryPassage as Passage


class Scope(Model):
    topicId: UUID
    revision: UUID


class Document(Model):
    documentId: UUID
    blockId: UUID
    title: str = Field(max_length=250)
    kind: Literal['markdown', 'pdf']
    text: str | None = Field(default=None, max_length=200000)
    # Only trusted, allowlisted storage URLs generated by .NET, never user URLs.
    url: str | None = Field(default=None, max_length=4000)


class IndexRequest(Model):
    topicId: UUID
    classId: UUID
    revision: UUID
    version: int = Field(ge=1)
    documents: list[Document] = Field(max_length=300)


class SearchRequest(Model):
    query: str = Field(min_length=1, max_length=4000)
    scopes: list[Scope] = Field(min_length=1, max_length=20)
    limit: int = Field(default=5, ge=1, le=8)


class AnswerRequest(Model):
    question: str = Field(min_length=1, max_length=2000)
    passages: list[Passage] = Field(max_length=8)


class GroundedAnswer(Model):
    answer: str = Field(min_length=1, max_length=6000)
    sourceIds: list[str] = Field(max_length=8)
    insufficientContext: bool

class DraftTest(Model):
    input: str = Field(max_length=8000)
    expectedOutput: str = Field(max_length=8000)
    isSample: bool

class DraftQuizItem(Model):
    question: str = Field(max_length=2000)
    choices: list[str] = Field(min_length=4, max_length=4)
    correctIndex: int = Field(ge=0, le=3)
    explanation: str = Field(max_length=2000)

class TeachingDraft(Model):
    title: str = Field(min_length=1, max_length=250)
    description: str = Field(min_length=1, max_length=12000)
    referenceSolution: str = Field(max_length=20000)
    tests: list[DraftTest] = Field(max_length=15)
    quiz: list[DraftQuizItem] = Field(max_length=5)
    sourceIds: list[str] = Field(min_length=1, max_length=8)

class DraftRequest(AnswerRequest):
    kind: Literal['exercise', 'quiz']
    language: Literal['python', 'cpp', 'java', 'csharp'] = 'python'
